content.content:
1	// 本地整库备份与恢复:导出快照(backup)与从快照整库恢复(restore)。
2	//
3	// - 快照为单个 JSON 文件,含格式标识、格式版本、负载的 SHA-256 完整性校验和
4	//   及三个业务存储(读数与修正/撤销历史、告警规则与历史、分组成员版本)的
5	//   完整内容;毫千瓦时为十进制字符串,任意大数精确保留。快照文件必须位于
6	//   数据目录之外;已有输出文件拒绝覆盖(原子无覆盖创建),备份失败不留下
7	//   可被当作成功快照的输出(先写临时文件再原子链接为最终名)。
8	// - 备份与恢复都校验三个业务存储的结构与关联:全库重复读数身份、修正项引用
9	//   缺失读数、撤销引用缺失修正、分组成员或规则目标不存在、告警引用缺失规则,
10	//   任一问题指出原因并拒绝。缺失的存储文件按对应空状态处理。
11	// - 恢复为整库替换:成功后业务状态完全等于快照,快照为空的部分清除原数据,
12	//   快照之后新增的读数、请求和告警不保留;只替换三个业务存储文件,目录内
13	//   其他文件保持不变;不自动评估或重新生成历史。恢复可用于当前存储已损坏
14	//   的目录,不解析原库。
15	// - 三个业务存储作为一次恢复提交:先写全部新内容到临时文件,再写恢复日志
16	//   (journal),然后整体换名提交,最后清理。读写或重命名失败回滚为恢复前
17	//   全部状态;进程在提交中断后,任一命令再次启动时先按日志前滚为完整快照
18	//   状态或回滚为完整旧状态,绝不查询或修改混合状态,无法完成时明确报错。
19	// - 备份与恢复执行期间对数据目录持有排他锁(锁文件,进程退出即 stale 可判),
20	//   不与其他进程同时读写同一目录。
21	
22	import { createHash } from 'node:crypto';
23	import {
24	  closeSync,
25	  existsSync,
26	  mkdirSync,
27	  openSync,
28	  readFileSync,
29	  renameSync,
30	  rmSync,
31	  statSync,
32	  writeFileSync,
33	  linkSync,
34	} from 'node:fs';
35	import { basename, isAbsolute, join, relative, resolve } from 'node:path';
36	import {
37	  alertFilePath,
38	  dataDirPath,
39	  dataFilePath,
40	  groupFilePath,
41	  loadData,
42	  parseStoreData,
43	  serializeStoreData,
44	  StoreError,
45	  type StoreData,
46	} from './store.ts';
47	import {
48	  loadAlertState,
49	  parseAlertState,
50	  serializeAlertState,
51	  type AlertState,
52	} from './alerts.ts';
53	import { loadGroups, parseGroups, serializeGroups, type Group } from './groups.ts';
54	import { formatIsoUtc } from './time.ts';
55	
56	const SNAPSHOT_FORMAT = 'meterwatch-snapshot';
57	const SNAPSHOT_VERSION = 1;
58	
59	const LOCK_NAME = 'backup-restore.lock';
60	const JOURNAL_NAME = 'restore.journal';
61	const JOURNAL_FORMAT = 'meterwatch-restore-journal';
62	const NEW_SUFFIX = '.restore-new';
63	const OLD_SUFFIX = '.restore-old';
64	
65	function err(message: string): void {
66	  console.error(`meterwatch: ${message}`);
67	}
68	
69	/** 三个业务存储文件的绝对路径(顺序固定,恢复作为一次提交)。 */
70	function storeFiles(): string[] {
71	  return [dataFilePath(), alertFilePath(), groupFilePath()];
72	}
73	
74	/** 快照路径是否位于数据目录之内(含等于目录本身)。 */
75	function isInsideDir(dir: string, p: string): boolean {
76	  const rel = relative(resolve(dir), resolve(p));
77	  return rel === '' || (!rel.startsWith('..') && !isAbsolute(rel));
78	}
79	
80	/**
81	 * 校验三个业务存储的关联一致性(结构合法性由各自的解析函数保证)。
82	 * 返回问题列表,空数组表示一致。
83	 */
84	function validateStores(data: StoreData, alerts: AlertState, groups: Group[]): string[] {
85	  const problems: string[] = [];
86	
87	  // 全库重复读数身份:同一设备同一实际时刻只允许一条存储记录。
88	  const readingKeys = new Set<string>();
89	  for (const r of data.readings) {
90	    const k = `${r.device} ${r.ts}`;
91	    if (readingKeys.has(k)) {
92	      problems.push(`duplicate stored reading for device '${r.device}' at ${formatIsoUtc(r.ts)}`);
93	    } else {
94	      readingKeys.add(k);
95	    }
96	  }
97	
98	  // 修正项必须引用已存读数。
99	  for (const c of data.corrections) {
100	    for (const it of c.items) {
101	      if (!readingKeys.has(`${it.device} ${it.ts}`)) {
102	        problems.push(
103	          `correction '${c.requestId}' references missing reading ` +
104	            `(device='${it.device}' at ${formatIsoUtc(it.ts)})`,
105	        );
106	      }
107	    }
108	  }
109	
110	  // 撤销必须引用已存修正。
111	  const correctionIds = new Set(data.corrections.map((c) => c.requestId));
112	  for (const u of data.undos) {
113	    if (!correctionIds.has(u.targetId)) {
114	      problems.push(`undo '${u.requestId}' references missing correction '${u.targetId}'`);
115	    }
116	  }
117	
118	  // 分组成员必须是已有读数的设备。
119	  const devices = new Set(data.readings.map((r) => r.device));
120	  for (const g of groups) {
121	    for (const v of g.versions) {
122	      for (const m of v.members) {
123	        if (!devices.has(m)) {
124	          problems.push(`group '${g.id}' member '${m}' has no stored readings`);
125	        }
126	      }
127	    }
128	  }
129	
130	  // 规则目标必须存在:设备规则绑定有读数的设备,分组规则绑定已配置分组。
131	  const groupIds = new Set(groups.map((g) => g.id));
132	  for (const r of alerts.rules) {
133	    if (r.targetType === 'device' && !devices.has(r.targetId)) {
134	      problems.push(`rule '${r.id}' targets device '${r.targetId}' which has no stored readings`);
135	    }
136	    if (r.targetType === 'group' && !groupIds.has(r.targetId)) {
137	      problems.push(`rule '${r.id}' targets unknown group '${r.targetId}'`);
138	    }
139	  }
140	
141	  // 告警必须引用已存规则。
142	  const ruleIds = new Set(alerts.rules.map((r) => r.id));
143	  for (const a of alerts.alerts) {
144	    if (!ruleIds.has(a.ruleId)) {
145	      problems.push(`alert '${a.id}' references missing rule '${a.ruleId}'`);
146	    }
147	  }
148	
149	  return problems;
150	}
151	
152	/**
153	 * 获取数据目录的排他锁;成功返回 null,失败返回错误消息。
154	 * 锁文件已存在且属存活进程时拒绝;属已退出进程时清理后重试一次。
155	 */
156	function acquireLock(dir: string): string | null {
157	  const lockPath = join(dir, LOCK_NAME);
158	  for (let attempt = 0; attempt < 2; attempt++) {
159	    try {
160	      const fd = openSync(lockPath, 'wx');
161	      try {
162	        writeFileSync(fd, String(process.pid));
163	      } finally {
164	        closeSync(fd);
165	      }
166	      return null;
167	    } catch (e) {
168	      const code = (e as NodeJS.ErrnoException).code;
169	      if (code !== 'EEXIST') {
170	        return `cannot acquire lock ${lockPath}: ${(e as Error).message}`;
171	      }
172	      let pid = Number.NaN;
173	      try {
174	        pid = Number(readFileSync(lockPath, 'utf8').trim());
175	      } catch {
176	        // 读不出属主按存活处理,不冒险清理。
177	      }
178	      let alive = true;
179	      if (Number.isInteger(pid) && pid > 0) {
180	        try {
181	          process.kill(pid, 0);
182	        } catch (ke) {
183	          alive = (ke as NodeJS.ErrnoException).code === 'EPERM';
184	        }
185	      }
186	      if (alive) {
187	        return (
188	          `another backup/restore process${Number.isInteger(pid) && pid > 0 ? ` (pid ${pid})` : ''} ` +
189	          `is operating on data directory ${dir}; wait for it to finish`
190	        );
191	      }
192	      try {
193	        rmSync(lockPath);
194	      } catch (re) {
195	        return `cannot remove stale lock ${lockPath}: ${(re as Error).message}`;
196	      }
197	    }
198	  }
199	  return `cannot acquire lock ${join(dir, LOCK_NAME)}`;
200	}
201	
202	function releaseLock(dir: string): void {
203	  try {
204	    rmSync(join(dir, LOCK_NAME));
205	  } catch {
206	    // 锁文件可能已被清理;释放失败不影响已完成的操作。
207	  }
208	}
209	
210	interface JournalFile {
211	  name: string;
212	  hadOld: boolean;
213	}
214	
215	interface Journal {
216	  files: JournalFile[];
217	}
218	
219	/** 解析恢复日志;结构非法返回 null(调用方按无法恢复处理,不猜测)。 */
220	function parseJournal(data: unknown): Journal | null {
221	  const o = data as Record<string, unknown>;
222	  if (
223	    o === null ||
224	    typeof o !== 'object' ||
225	    o.format !== JOURNAL_FORMAT ||
226	    o.version !== 1 ||
227	    !Array.isArray(o.files) ||
228	    o.files.length === 0
229	  ) {
230	    return null;
231	  }
232	  const files: JournalFile[] = [];
233	  for (const f of o.files as Array<Record<string, unknown>>) {
234	    if (
235	      f === null ||
236	      typeof f !== 'object' ||
237	      typeof f.name !== 'string' ||
238	      f.name.length === 0 ||
239	      typeof f.hadOld !== 'boolean'
240	    ) {
241	      return null;
242	    }
243	    files.push({ name: f.name, hadOld: f.hadOld });
244	  }
245	  return { files };
246	}
247	
248	/**
249	 * 回滚到恢复前状态:凡有旧文件备份的换回原文件,原本不存在的文件删除新文件;
250	 * 清理临时文件与日志。任何一步失败抛错。
251	 */
252	function rollback(dir: string, journal: Journal): void {
253	  for (const f of journal.files) {
254	    const target = join(dir, f.name);
255	    const oldPath = target + OLD_SUFFIX;
256	    const newPath = target + NEW_SUFFIX;
257	    if (existsSync(oldPath)) {
258	      // 旧文件备份必为常规文件(本进程只会写出常规文件);否则按被篡改处理,不猜测。
259	      if (!statSync(oldPath).isFile()) {
260	        throw new StoreError(`restore backup ${oldPath} is not a regular file`);
261	      }
262	      if (existsSync(target)) rmSync(target);
263	      renameSync(oldPath, target);
264	    } else if (!f.hadOld && !existsSync(newPath) && existsSync(target)) {
265	      // 新文件已被换入且原本不存在:删除以恢复原状。
266	      rmSync(target);
267	    }
268	  }
269	  for (const f of journal.files) {
270	    const newPath = join(dir, f.name) + NEW_SUFFIX;
271	    if (existsSync(newPath)) {
272	      try {
273	        rmSync(newPath);
274	      } catch {
275	        // 残留的临时文件不影响业务状态,下次启动再清理。
276	      }
277	    }
278	  }
279	  rmSync(join(dir, JOURNAL_NAME));
280	}
281	
282	/**
283	 * 前滚到完整快照状态:把仍待换入的新文件换入,删除日志与旧文件备份。
284	 * 任何一步失败抛错。
285	 */
286	function rollForward(dir: string, journal: Journal): void {
287	  for (const f of journal.files) {
288	    const newPath = join(dir, f.name) + NEW_SUFFIX;
289	    if (existsSync(newPath)) {
290	      // 待换入的新内容必为常规文件(本进程只会写出常规文件);否则按被篡改
291	      // 处理,中止前滚,由调用方回退或报错,绝不把异常内容当作业务存储。
292	      if (!statSync(newPath).isFile()) {
293	        throw new StoreError(`restore temp file ${newPath} is not a regular file`);
294	      }
295	      renameSync(newPath, join(dir, f.name));
296	    }
297	  }
298	  rmSync(join(dir, JOURNAL_NAME));
299	  for (const f of journal.files) {
300	    const oldPath = join(dir, f.name) + OLD_SUFFIX;
301	    if (existsSync(oldPath)) rmSync(oldPath);
302	  }
303	}
304	
305	/**
306	 * 任一命令启动时调用:若上次恢复在提交中断,先把数据目录恢复为完整快照
307	 * 状态(优先)或完整旧状态,绝不留下混合状态。成功(或无需恢复)返回 null,
308	 * 无法完成返回错误消息。
309	 */
310	export function recoverInterruptedRestore(): string | null {
311	  const dir = dataDirPath();
312	  const journalPath = join(dir, JOURNAL_NAME);
313	  if (existsSync(journalPath)) {
314	    let journal: Journal | null = null;
315	    try {
316	      journal = parseJournal(JSON.parse(readFileSync(journalPath, 'utf8')));
317	    } catch {
318	      journal = null;
319	    }
320	    if (journal === null) {
321	      return (
322	        `cannot recover data directory ${dir}: restore journal ${journalPath} is unreadable or invalid; ` +
323	        `the directory may hold a mixed state, restore it manually from a snapshot`
324	      );
325	    }
326	    try {
327	      rollForward(dir, journal);
328	      console.error('meterwatch: completed an interrupted restore: snapshot state committed');
329	      return null;
330	    } catch {
331	      // 前滚失败则尝试回滚为完整旧状态。
332	    }
333	    try {
334	      rollback(dir, journal);
335	      console.error('meterwatch: rolled back an interrupted restore: previous state preserved');
336	      return null;
337	    } catch (e) {
338	      return (
339	        `cannot recover data directory ${dir} to a consistent state: ${(e as Error).message}; ` +
340	        `restore it manually from a snapshot`
341	      );
342	    }
343	  }
344	  // 无日志:提交要么未开始(可能残留新临时文件),要么已完整完成(可能残留旧文件
345	  // 备份);两种残留都不影响业务状态,清理即可。清理失败明确报错,不继续启动。
346	  for (const path of storeFiles()) {
347	    for (const leftover of [path + NEW_SUFFIX, path + OLD_SUFFIX]) {
348	      if (existsSync(leftover)) {
349	        try {
350	          rmSync(leftover);
351	        } catch (e) {
352	          return `cannot clean up interrupted restore leftover ${leftover}: ${(e as Error).message}`;
353	        }
354	      }
355	    }
356	  }
357	  return null;
358	}
359	
360	/**
361	 * 把三个业务存储的新内容作为一次恢复提交。失败抛 StoreError 并尽力回滚为
362	 * 提交前状态;回滚也失败时错误中明确说明目录可能处于混合状态。
363	 */
364	function commitRestore(dir: string, files: Array<{ path: string; body: string }>): void {
365	  const journalPath = join(dir, JOURNAL_NAME);
366	  const journal: Journal = {
367	    files: files.map((f) => ({ name: basename(f.path), hadOld: existsSync(f.path) })),
368	  };
369	
370	  // 阶段一:写全部新内容到临时文件,再原子写入恢复日志。此阶段失败或中断
371	  // 不影响现有业务文件;残留的临时文件由下次启动清理。
372	  try {
373	    for (const f of files) {
374	      writeFileSync(f.path + NEW_SUFFIX, f.body, 'utf8');
375	    }
376	    const journalTmp = `${journalPath}.tmp-${process.pid}`;
377	    writeFileSync(
378	      journalTmp,
379	      JSON.stringify({ format: JOURNAL_FORMAT, version: 1, files: journal.files }, null, 2) + '\n',
380	      'utf8',
381	    );
382	    renameSync(journalTmp, journalPath);
383	  } catch (e) {
384	    for (const f of files) {
385	      try {
386	        rmSync(f.path + NEW_SUFFIX);
387	      } catch {
388	        // 清理失败不掩盖原始错误。
389	      }
390	    }
391	    throw new StoreError(`cannot prepare restore in ${dir}: ${(e as Error).message}; nothing was changed`);
392	  }
393	
394	  // 阶段二:整体换名提交(旧文件换为备份,新文件换入),然后删除日志与备份。
395	  // 此阶段中断由下次启动按日志前滚或回滚;受控失败按已完成的步骤精确回滚
396	  // (只动本次自己换名的文件,不触碰目录内任何其他文件)。
397	  const movedToOld: string[] = [];
398	  const movedIn: string[] = [];
399	  try {
400	    for (const f of files) {
401	      if (existsSync(f.path)) {
402	        renameSync(f.path, f.path + OLD_SUFFIX);
403	        movedToOld.push(f.path);
404	      }
405	    }
406	    for (const f of files) {
407	      renameSync(f.path + NEW_SUFFIX, f.path);
408	      movedIn.push(f.path);
409	    }
410	    rmSync(journalPath);
411	    for (const f of files) {
412	      if (existsSync(f.path + OLD_SUFFIX)) rmSync(f.path + OLD_SUFFIX);
413	    }
414	  } catch (e) {
415	    try {
416	      // 撤销已换入的新文件,再把已换出的旧文件换回原位;未完成的步骤不动。
417	      for (const path of movedIn) {
418	        if (existsSync(path)) rmSync(path);
419	      }
420	      for (const path of movedToOld) {
421	        renameSync(path + OLD_SUFFIX, path);
422	      }
423	      for (const f of files) {
424	        if (existsSync(f.path + NEW_SUFFIX)) rmSync(f.path + NEW_SUFFIX);
425	      }
426	      rmSync(journalPath);
427	    } catch (re) {
428	      throw new StoreError(
429	        `restore failed (${(e as Error).message}) and rollback also failed (${(re as Error).message}); ` +
430	          `data directory ${dir} may be in a mixed state, restore it manually from a snapshot`,
431	      );
432	    }
433	    throw new StoreError(`restore failed: ${(e as Error).message}; previous state preserved`);
434	  }
435	}
436	
437	/** 各存储内容汇总的一行数量报告。 */
438	function countsReport(data: StoreData, alerts: AlertState, groups: Group[]): string {
439	  const versions = groups.reduce((n, g) => n + g.versions.length, 0);
440	  return (
441	    `${data.readings.length} reading(s), ${data.corrections.length} correction(s), ` +
442	    `${data.undos.length} undo(s), ${groups.length} group(s) (${versions} member version(s)), ` +
443	    `${alerts.rules.length} rule(s), ${alerts.alerts.length} alert(s)`
444	  );
445	}
446	
447	/**
448	 * 导出全库快照。只读取业务存储,不改写业务数据;输出文件必须位于数据目录
449	 * 之外且不得已存在。返回进程退出码。
450	 */
451	export function cmdBackup(outPath: string): number {
452	  const dir = dataDirPath();
453	  if (isInsideDir(dir, outPath)) {
454	    err(`snapshot file '${outPath}' must be located outside the data directory ${dir}`);
455	    return 2;
456	  }
457	
458	  mkdirSync(dir, { recursive: true });
459	  const lockError = acquireLock(dir);
460	  if (lockError !== null) {
461	    err(lockError);
462	    return 1;
463	  }
464	  try {
465	    let data: StoreData;
466	    let alerts: AlertState;
467	    let groups: Group[];
468	    try {
469	      data = loadData(dataFilePath());
470	      alerts = loadAlertState(alertFilePath());
471	      groups = loadGroups(groupFilePath());
472	    } catch (e) {
473	      if (e instanceof StoreError) {
474	        err(e.message);
475	        return 1;
476	      }
477	      throw e;
478	    }
479	
480	    const problems = validateStores(data, alerts, groups);
481	    if (problems.length > 0) {
482	      for (const p of problems) err(p);
483	      err(`backup rejected: ${problems.length} consistency problem(s); no snapshot was written`);
484	      return 1;
485	    }
486	
487	    const payload = {
488	      readings: serializeStoreData(data),
489	      alerts: serializeAlertState(alerts),
490	      groups: serializeGroups(groups),
491	    };
492	    const checksum = createHash('sha256').update(JSON.stringify(payload), 'utf8').digest('hex');
493	    const body =
494	      JSON.stringify(
495	        {
496	          format: SNAPSHOT_FORMAT,
497	          version: SNAPSHOT_VERSION,
498	          checksum: `sha256:${checksum}`,
499	          payload,
500	        },
501	        null,
502	        2,
503	      ) + '\n';
504	
505	    // 先写临时文件,再原子链接为最终名:已存在的输出拒绝覆盖,失败不留下
506	    // 可被当作成功快照的输出。
507	    const out = resolve(outPath);
508	    const tmp = `${out}.tmp-${process.pid}`;
509	    try {
510	      writeFileSync(tmp, body, 'utf8');
511	      linkSync(tmp, out);
512	    } catch (e) {
513	      if ((e as NodeJS.ErrnoException).code === 'EEXIST') {
514	        err(`output file '${outPath}' already exists; refusing to overwrite`);
515	      } else {
516	        err(`cannot write snapshot '${outPath}': ${(e as Error).message}`);
517	      }
518	      return 1;
519	    } finally {
520	      try {
521	        rmSync(tmp);
522	      } catch {
523	        // 临时文件可能未创建;清理失败不影响结果。
524	      }
525	    }
526	
527	    console.log(`snapshot written to '${outPath}': ${countsReport(data, alerts, groups)}`);
528	    return 0;
529	  } finally {
530	    releaseLock(dir);
531	  }
532	}
533	
534	/**
535	 * 从快照整库恢复。快照须通过格式版本与完整性校验,且三个业务存储的结构与
536	 * 关联一致,否则不开始替换。成功后业务状态完全等于快照。返回进程退出码。
537	 */
538	export function cmdRestore(snapshotPath: string): number {
539	  const dir = dataDirPath();
540	  if (isInsideDir(dir, snapshotPath)) {
541	    err(`snapshot file '${snapshotPath}' must be located outside the data directory ${dir}`);
542	    return 2;
543	  }
544	
545	  let text: string;
546	  try {
547	    text = readFileSync(resolve(snapshotPath), 'utf8');
548	  } catch (e) {
549	    err(`cannot read snapshot '${snapshotPath}': ${(e as Error).message}`);
550	    return 1;
551	  }
552	  let envelope: unknown;
553	  try {
554	    envelope = JSON.parse(text);
555	  } catch {
556	    err(`snapshot '${snapshotPath}' is corrupted (invalid JSON or truncated); nothing was restored`);
557	    return 1;
558	  }
559	  const env = envelope as Record<string, unknown>;
560	  if (env === null || typeof env !== 'object' || env.format !== SNAPSHOT_FORMAT) {
561	    err(`snapshot '${snapshotPath}' is not a meterwatch snapshot; nothing was restored`);
562	    return 1;
563	  }
564	  if (env.version !== SNAPSHOT_VERSION) {
565	    err(
566	      `snapshot '${snapshotPath}' has unsupported format version ${String(env.version)} ` +
567	        `(this build supports version ${SNAPSHOT_VERSION}); nothing was restored`,
568	    );
569	    return 1;
570	  }
571	  const payloadText = JSON.stringify(env.payload) ?? '';
572	  const checksum = createHash('sha256').update(payloadText, 'utf8').digest('hex');
573	  if (typeof env.checksum !== 'string' || env.checksum !== `sha256:${checksum}`) {
574	    err(`snapshot '${snapshotPath}' failed its integrity check; nothing was restored`);
575	    return 1;
576	  }
577	
578	  const payload = env.payload as Record<string, unknown>;
579	  let data: StoreData;
580	  let alerts: AlertState;
581	  let groups: Group[];
582	  try {
583	    data = parseStoreData(payload?.readings, `snapshot '${snapshotPath}' readings store`);
584	    alerts = parseAlertState(payload?.alerts, `snapshot '${snapshotPath}' alerts store`);
585	    groups = parseGroups(payload?.groups, `snapshot '${snapshotPath}' groups store`);
586	  } catch (e) {
587	    if (e instanceof StoreError) {
588	      err(`${e.message}; nothing was restored`);
589	      return 1;
590	    }
591	    throw e;
592	  }
593	  const problems = validateStores(data, alerts, groups);
594	  if (problems.length > 0) {
595	    for (const p of problems) err(p);
596	    err(`restore rejected: snapshot has ${problems.length} consistency problem(s); nothing was restored`);
597	    return 1;
598	  }
599	
600	  mkdirSync(dir, { recursive: true });
601	  const lockError = acquireLock(dir);
602	  if (lockError !== null) {
603	    err(lockError);
604	    return 1;
605	  }
606	  try {
607	    commitRestore(dir, [
608	      { path: dataFilePath(), body: JSON.stringify(serializeStoreData(data), null, 2) + '\n' },
609	      { path: alertFilePath(), body: JSON.stringify(serializeAlertState(alerts), null, 2) + '\n' },
610	      { path: groupFilePath(), body: JSON.stringify(serializeGroups(groups), null, 2) + '\n' },
611	    ]);
612	  } catch (e) {
613	    if (e instanceof StoreError) {
614	      err(e.message);
615	      return 1;
616	    }
617	    throw e;
618	  } finally {
619	    releaseLock(dir);
620	  }
621	
622	  console.log(`restored from snapshot '${snapshotPath}': ${countsReport(data, alerts, groups)}`);
623	  return 0;
624	}
